insert into batch.readiness_wait (
    tenant_id, workflow_definition_id, workflow_code, calendar_code, schedule_version,
    depends_on_job_codes, biz_date, scheduled_fire_time, deferred_since, deadline,
    wait_status, trace_id
) values (
    #{tenantId}, #{workflowDefinitionId}, #{workflowCode}, #{calendarCode},
    #{scheduleVersion}, #{dependsOnJobCodes}, #{bizDate}, #{scheduledFireTime},
    #{deferredSince}, #{deadline}, 'PENDING', #{traceId}
)
on conflict (tenant_id, workflow_definition_id, scheduled_fire_time) do nothing
